Final Model
The workflow-set comparison above told us the random forest wins. Let’s fit it once more on the full training set so we have a single model object to interrogate:

final &lt;- workflow() |&gt;
  add_recipe(rec) |&gt;
  add_model(rf_model) |&gt;
  fit(data = camels_train)

Getting the Data

Streamflow
Download daily streamflow for the Poudre at Mouth (USGS 06752260) and aggregate to monthly means.

poudre_flow &lt;- readNWISdv(
  siteNumber = "06752260",
  parameterCd = "00060",
  startDate   = "2013-01-01",
  endDate     = "2023-12-31"
) |&gt;
  renameNWISColumns() |&gt;
  mutate(Date = yearmonth(Date)) |&gt;
  group_by(Date) |&gt;
  summarise(Flow = mean(Flow))



Historic Climate (GridMET)
We will use climateR::getTerraClim() to download monthly climate data for the Poudre basin (max temperature, precipitation, solar radiation). The exactextractr package spatially averages each raster layer over the basin polygon.

basin &lt;- findNLDI(nwis = "06752260", find = "basin")

sdate &lt;- as.Date("2013-01-01")
edate &lt;- as.Date("2023-12-31")

gm &lt;- getTerraClim(
  AOI       = basin$basin,
  var       = c("tmax", "ppt", "srad"),
  startDate = sdate,
  endDate   = edate
) |&gt;
  unlist() |&gt;
  rast() |&gt;
  exact_extract(basin$basin, "mean", progress = FALSE)

historic &lt;- mutate(gm, id = "gridmet") |&gt;
  pivot_longer(cols = -id) |&gt;
  mutate(name = sub("^mean\\.", "", name)) |&gt;
  tidyr::extract(name, into = c("var", "index"), "(.*)_([^_]+$)") |&gt;
  mutate(index = as.integer(index)) |&gt;
  mutate(Date = yearmonth(seq.Date(sdate, edate, by = "month")[as.numeric(index)])) |&gt;
  pivot_wider(id_cols = Date, names_from = var, values_from = value) |&gt;
  right_join(poudre_flow, by = "Date")

# Validate: should have 132 rows (11 years × 12 months). If fewer, climate data
# is missing for some months and those flow months were silently dropped.
stopifnot("Climate join dropped flow months — check GridMET download" = nrow(historic) == 132)



Future Climate (MACA)
Any time exogenous predictors are used for forecasting, future values of those predictors must also be available. We use MACA — a statistically downscaled climate dataset developed by the same group as GridMET — to get projected temperature, precipitation, and solar radiation through 2033.

sdate &lt;- as.Date("2024-01-01")
edate &lt;- as.Date("2033-12-31")

maca &lt;- getMACA(
  AOI      = basin$basin,
  var      = c("tasmax", "pr", "rsds"),
  timeRes  = "month",
  startDate = sdate,
  endDate   = edate
) |&gt;
  unlist() |&gt;
  rast() |&gt;
  exact_extract(basin$basin, "mean", progress = FALSE)

Multiple ensembles available per model. Since `ensemble = NULL`, we default to:
    &gt; CCSM4 [rcp45] [r6i1p1]
    &gt; CCSM4 [rcp45] [r6i1p1]
    &gt; CCSM4 [rcp45] [r6i1p1]


Warning in .local(x, y, ...): Polygons transformed to raster CRS. To avoid
on-the-fly coordinate transformation, ensure that st_crs() returns the same
result for both raster and polygon inputs.

future &lt;- mutate(maca, id = "maca") |&gt;
  pivot_longer(cols = -id) |&gt;
  mutate(name = sub("^mean\\.", "", name)) |&gt;
  tidyr::extract(name, into = c("var", "index"), "(.*)_([^_]+$)") |&gt;
  mutate(index = as.integer(index)) |&gt;
  mutate(Date = yearmonth(seq.Date(sdate, edate, by = "month")[as.numeric(index)])) |&gt;
  pivot_wider(id_cols = Date, names_from = var, values_from = value)

# Rename the 3 climate columns to match GridMET names (Date column stays first)
stopifnot("Unexpected MACA column count" = ncol(future) == 4)
names(future)[2:4] &lt;- c("ppt", "srad", "tmax")  # order matches getMACA var request
future &lt;- mutate(future, tmax = tmax - 273.15)   # Kelvin → °C

3.1 Reading and Cleaning the NID Data
The NID dataset is available as a CSV download from the USACE website here. The data is read in with readr::read_csv, column names are standardized to snake_case with janitor::clean_names(), rows without location values are removed with !is.na(), the data.frame is converted to an sf object by defining the coordinates and CRS, transformed to a CONUS AEA (EPSG:5070) projection to match the tessellation, and filtered to those within the CONUS boundary.


Code
# Prefer a local NID CSV named `nation.csv`; otherwise download to that filename
nid_url &lt;- "https://nid.sec.usace.army.mil/api/nation/csv"
dir.create("data", showWarnings = FALSE)
nid_dest &lt;- "data/nation.csv"
if (file.exists(nid_dest)) {
  message("Using local NID file: ", nid_dest)
} else {
  tryCatch({
    message("Downloading NID CSV to: ", nid_dest)
    download.file(nid_url, nid_dest, quiet = FALSE, mode = "wb")
  }, error = function(e) {
    message("NID download failed: ", e$message)
  })
}

# read the CSV (will error if download failed and file missing)
if (!file.exists(nid_dest)) stop("NID CSV not found at ", nid_dest)
dams &lt;- readr::read_csv(nid_dest, skip =1, show_col_types = FALSE) |&gt; 
  janitor::clean_names()

usa &lt;- AOI::aoi_get(state = "conus") %&gt;% 
  st_union() %&gt;% 
  st_transform(5070)

dams2 &lt;- dams %&gt;% 
  filter(!is.na(latitude)) %&gt;%
  st_as_sf(coords = c("longitude", "latitude"), crs = 4326) %&gt;% 
  st_transform(5070) %&gt;% 
  st_filter(usa)

3.2 A Point-in-Polygon Function
An efficient point-in-polygon function takes points as arg1, polygons as arg2, and the name of the id column as arg3. It makes use of spatial and non-spatial joins, sf coercion, and dplyr::count. The returned object is the input sf object with a column n counting the number of points in each tile. The function checks that both inputs are sf objects, transforms the points to match the polygon CRS if they differ, and uses a left join so that polygons with zero points still appear with a count.


Code
#PIP funciton 
point_in_polygon &lt;- function(points, polygon, poly_id = id, point_id = nid_id) {

  if (!inherits(points, "sf")) stop("Points must be sf object")
  if (!inherits(polygon, "sf")) stop("Polygon must be sf object")

  tryCatch({
    if (st_crs(points) != st_crs(polygon)) {
      print("CRS do not match, transforming to polygon CRS")
       points &lt;- st_transform(points, st_crs(polygon))
       }
  }, error = function(e) {
    print(paste("CRS transform failed:", e$message))
    stop(e)
  })

  tryCatch({

 result &lt;-  st_join(polygon, points) %&gt;% 
    st_drop_geometry() %&gt;%
      group_by({{ poly_id }}) %&gt;%                         
      summarise(n = sum(!is.na({{ point_id }}))) %&gt;%  
      left_join(polygon, by = join_by({{ poly_id }})) %&gt;%  
      st_as_sf()

   return(result)

  }, error = function(e) {
    print(paste("Spatial join failed:", e$message))
    stop(e)
  })
}


The function is applied to each of the five tessellated surfaces, with the dams as points, each tessellation as the polygons, and the respective id column.


Code
voroni_pip &lt;- point_in_polygon(dams2, voroni_trim)

triangle_pip &lt;- point_in_polygon(dams2, triangle_trim)

square_pip &lt;- point_in_polygon(dams2, square_trim)

hex_pip &lt;- point_in_polygon(dams2, hex_trim)

counties_id &lt;- us_counties %&gt;% 
  mutate(id = 1:n())

counties_pip &lt;- point_in_polygon(dams2, counties_id)

